{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is low (≤0.33) and historical prices show mean reversion toward lower levels.",
    "Increase forecast bias upward when sentiment is positive (≥0.50) and recent prices are trending upward, especially after a spike.",
    "Apply lag correction: if true outcome is significantly higher than forecast 3-5 days after a spike, reduce forecast for next period by 2-5%.",
    "Avoid over-optimism in short-term forecasts (1-7 days) when sentiment is neutral or negative — cap forecast at 1-2% below recent high.",
    "For 14+ day horizons, allow for mean reversion to 30-day moving average if sentiment is weak or flat.",
    "If sentiment is positive but forecast is consistently below true outcome, increase forecast by 1-3% for next period to account for sentiment-driven momentum."
  ]
}
